import{_ as t,o as l,c as s,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/schueler/akt-halbj-bemerkungen-1.png",u="/bilder/schueler/akt-halbj-bemerkungen-2.png",d="/bilder/schueler/akt-halbj-bemerkungen-3.png",f=JSON.parse('{"title":"Bemerkungen zum Lernabschnitt erfassen","description":"","frontmatter":{"title":"Bemerkungen zum Lernabschnitt erfassen","source_pageid":505,"source_revision":5316},"headers":[],"relativePath":"schild3/schueler/bemerkungen-aktuelles-halbjahr-aktueller-abschnitt.md","filePath":"schild3/schueler/bemerkungen-aktuelles-halbjahr-aktueller-abschnitt.md"}'),o={name:"schild3/schueler/bemerkungen-aktuelles-halbjahr-aktueller-abschnitt.md"};function g(c,r,h,m,k,b){return l(),s("div",null,[...r[0]||(r[0]=[i('<h1 id="bemerkungen-zum-lernabschnitt-erfassen" tabindex="-1">Bemerkungen zum Lernabschnitt erfassen <a class="header-anchor" href="#bemerkungen-zum-lernabschnitt-erfassen" aria-label="Permalink to &quot;Bemerkungen zum Lernabschnitt erfassen&quot;">​</a></h1><p>Erfassen Sie Zeugnisbemerkungen, Angaben zum Arbeits- und Sozialverhalten und zum außerunterrichtlichen Engagement. Nutzen Sie bei Bedarf die hinterlegten Floskeln und Variablen.</p><p><a href="/bilder/schueler/akt-halbj-bemerkungen-1.png"><img src="'+a+'" alt="Übersicht der Bemerkungen zu einem Lernabschnitt." loading="lazy"></a></p><p><em>Übersicht der Bemerkungen zu einem Lernabschnitt.</em></p><p>Zu jedem Lernabschnitt können <em>Bemerkungen</em> erfasst werden. Diese können über Reports ausgegeben werden, zum Beispiel auf Zeugnissen.</p><p>Es können Bemerkungen zu unterschiedlichen Kategorien erfasst werden, wie dem <strong>Arbeits- und Sozialverhalten</strong>, den <strong>Zeugnisbemerkungen und dem Außerunterrichtlichen Engagement</strong>. Eine <strong>Bemerkung zum Förderschwerpunkt</strong> kann nur eingetragen werden, wenn beim Schüler im aktuellen Halbjahr ein Förderschwerpunkt hinterlegt wurde.</p><p><a href="/bilder/schueler/akt-halbj-bemerkungen-2.png"><img src="'+u+'" alt="Der Floskeleditor für Bemerkungen." loading="lazy"></a></p><p><em>Der Floskeleditor für Bemerkungen.</em></p><p>Doppelklicken Sie in das gewünschte Bemerkungsfeld. Im folgenden Fenster können Sie den vorhandenen Text bearbeiten.</p><p>Sie können den Text direkt eingeben oder vorbereitete <strong>Floskeln</strong>, also wiederverwendbare Textbausteine, mit einem Doppelklick einfügen.</p><p>Im Floskeleditor kann über das Dropdown-Menü zum Filtern eingestellt werden, welche <em>Floskelgruppe</em> angezeigt wird. Per Standard ist der Filter auf das Feld eingestellt, über welches der Floskeleditor geöffnet wurde.</p><p>Floskeln können <strong>Variablen</strong> enthalten, die beim Einfügen durch Daten der ausgewählten Person ersetzt werden. Zum Beispiel steht <code>$Vorname$</code> anschließend für deren Vornamen.</p><p>Mit einem Haken bei <strong>Mehrfache Nennung des Vornamens vermeiden</strong> wird bei weiteren direkt im Anschluss eingefügten Floskeln der Vorname durch &quot;er&quot; oder &quot;sie&quot; ersetzt.</p>',13),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Neue Floskeln können über "),e("em",null,'"Kataloge"'),n(" ➜ "),e("em",null,'"Floskeln bearbeiten"'),n(" zentral angelegt und dann hier genutzt werden.")])],-1),e("p",null,[e("a",{href:"/bilder/schueler/akt-halbj-bemerkungen-3.png"},[e("img",{src:d,alt:"Beispielergebnisse einer Bearbeitung.",loading:"lazy"})])],-1),e("p",null,[e("em",null,"Beispielergebnisse einer Bearbeitung.")],-1),e("p",null,[n("Unter den Bemerkungen wird hier auch der Bereich für die "),e("em",null,"Zeugnis- und Abschlussdaten"),n(" des aktuellen Abschnitts eingeblendet.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Bemerkungen_(Aktuelles_Halbjahr_/_Aktueller_Abschnitt",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5316.")],-1)])])}const _=t(o,[["render",g]]);export{f as __pageData,_ as default};
